"""Build a portable team checkpoint with exact recorded prompts and figures."""
import base64,html,json
from pathlib import Path

REPO=Path(__file__).resolve().parents[1]
OUT=REPO/'artifacts/pipeline-checkpoint';OUT.mkdir(parents=True,exist_ok=True)
PAIR=REPO/'artifacts/pipeline-set4-clean'

def esc(value):return html.escape(str(value))
def block(value):return '<pre>'+esc(value if isinstance(value,str) else json.dumps(value,indent=2,ensure_ascii=False))+'</pre>'
def details(title,body):return '<details><summary>'+esc(title)+'</summary>'+body+'</details>'

requests=[];systems={};instructions={};examples={}
for variant,condition in [('swarm','cooperative'),('private','fixed')]:
    directory=PAIR/variant/condition/'seed_74'
    for path in sorted((directory/'calls').glob('*/request.json')):
        q=json.loads(path.read_text(encoding='utf-8'));phase=q['context']['phase']
        requests.append({'variant':variant,'call':q['call'],'agent':q['agent'],'messages':q['messages'],'context':q['context']})
        systems.setdefault(variant,q['messages'][0]['content'])
        instructions.setdefault((variant,phase),q['context']['instruction'])
        examples.setdefault((variant,phase),q['context'])
audit={v:json.loads((PAIR/v/c/'seed_74/audit.json').read_text()) for v,c in [('swarm','cooperative'),('private','fixed')]}
manifest=json.loads((PAIR/'analysis/manifest.json').read_text())
assignments=json.loads((PAIR/'assignments.json').read_text())
tasks=[json.loads(line) for line in (REPO/'bench/set_4.jsonl').read_text(encoding='utf-8').splitlines() if line.strip()]
cfg=json.loads((PAIR/'swarm/cooperative/seed_74/manifest.json').read_text())['config']

figures=[
 ('Reference set_4: arc','pipeline-set4-clean/analysis/full_arc_w2048.png','Original set_4 reference, NOT a ladder rung. Same tasks, same assignments: the swarm arc persists. Private solving is close to swarm solving. Orange has no distribution or exchange phase. Its solving timeline is mapped by relative progress, not wall-clock time.'),
 ('Reference set_4: matched','pipeline-set4-clean/analysis/paired_w400.png','Original set_4 reference, NOT a ladder rung. Left: relative solving progress with ten retained vectors. Right: natural token windows, dropping finished agents. Dense points can repeat the same short-agent windows; line segments are not additional observations.'),
 ('Ladder 1: three groups','pipeline-replicates/solving_three_groups.png','Rung 1, three groups per condition. Thin lines are individual groups; bands are sample SD, not confidence intervals. Shared coverage ends at 0.781 progress. Historical seed-3 controls include recovery differences.'),
 ('Vector count','pipeline-diagnostics/vector_count_effect.png','Removing vectors from the SAME texts increases R and lowers effective dimension. Mean pairwise cosine across all subsets removes the algebraic self-similarity count term. Bands are subset percentiles, not new experimental replicates.'),
 ('Legacy diagnosis','pipeline-legacy-diagnosis/allocation_without_communication.png','Reassembly of existing legacy vectors: one distinct task per agent versus task collisions. Separation appears without peer information during solving. This ablation does not fully explain the original shuffled R gap; task allocation, lengths and assembly differ.')]
for title,path,caption in [
    ('Chat lengths','pipeline-chat-lengths/chat_tokens.png','Task-distribution chat tokens per agent, across all four ladder rungs. Only the text of send messages is counted; JSON syntax and private reasoning are excluded.'),
    ('CoT lengths','pipeline-chat-lengths/reasoning_tokens.png','Private API-returned reasoning tokens per agent during task distribution, in thousands. CoT is saved and included in current embeddings but not sent to peers. Totals retain all observed distribution turns, including retries.')]:
    if (REPO/'artifacts'/path).exists():figures.append((title,path,caption))
buttons=[];panels=[]
ladder_root=REPO/'artifacts/pipeline-ladder'
if any((ladder_root/f'rung_{r}/analysis/full_arc_w2048.png').exists() for r in range(1,5)):
    ladder_figures=[]
    for rung in range(1,5):
        path=f'pipeline-ladder/rung_{rung}/analysis/full_arc_w2048.png'
        if (REPO/'artifacts'/path).exists():
            ladder_figures.append((f'Ladder {rung}: arc',path,f'Ladder rung {rung}: full stateful swarm arc versus the same one-task-per-agent assignment without exchange. Blue has real distribution and commit observations; orange has solving only, mapped by relative progress. One pair, no uncertainty bands.'))
            matched=f'pipeline-ladder/rung_{rung}/analysis/paired_w400.png'
            if (REPO/'artifacts'/matched).exists():
                ladder_figures.append((f'Ladder {rung}: matched',matched,f'Ladder rung {rung}, 400-token windows: swarm solving versus independent agents with identical task assignments. Left: relative progress retaining ten vectors; right: natural token clock with finished agents removed. No original set_4 data in this chart.'))
    overview=ladder_root/'full_arcs_overview.png'
    if overview.exists():ladder_figures.insert(0,('Ladder overview','pipeline-ladder/full_arcs_overview.png','All four ladder rungs on the SAME vertical scale. Coordinates are within-phase relative progress, not wall-clock time. One pair per rung; no uncertainty bands. Orange contains private solving only.'))
    figures=ladder_figures+figures
for i,(title,path,caption) in enumerate(figures):
    image_path=REPO/'artifacts'/path
    data=base64.b64encode(image_path.read_bytes()).decode()
    buttons.append(f'<button class="tab {"selected" if i==0 else ""}" data-target="figure{i}" aria-selected="{str(i==0).lower()}">{esc(title)}</button>')
    panels.append(f'<figure id="figure{i}" class="figure-panel" {"" if i==0 else "hidden"}><figcaption>{esc(caption)}</figcaption><img src="data:image/png;base64,{data}" alt="{esc(title)}" loading="lazy" title="Click to enlarge"></figure>')

prompts=details('Swarm — exact system prompt (Agent 1)',block(systems['swarm']))
prompts+=details('Private control — exact system prompt (Agent 1)',block(systems['private']))
for key,value in instructions.items():prompts+=details(f'{key[0].title()} / {key[1]} — exact phase instruction',block(value))
for key,value in examples.items():prompts+=details(f'{key[0].title()} / {key[1]} — complete recorded user context',block(value))
prompts+=details('All ten original task prompts',''.join(details(t['id'],block(t['prompt'])) for t in tasks))
prompts+=details('Input assembly and exact archive','<p>Every API input is the agent’s retained private message history plus a final user message containing the current context as JSON. Successful outputs and rejection feedback stay in that agent’s history. Other agents receive published messages/results, not private reasoning. The recorded system prompt stays available in every phase.</p><p>The embedded archive contains all 50 recorded API inputs, including accumulated histories, but no authentication headers, credentials or reference-answer metadata.</p><button id="download">Download all 50 exact inputs as JSON</button>')

assignment_rows=''.join(f'<tr><td>{esc(i)}</td><td>{esc(t)}</td></tr>' for i,t in sorted(assignments.items(),key=lambda x:int(x[0])))
summary=json.loads((PAIR/'analysis/summary.json').read_text())
result_rows=''.join(f"<tr><td>{r['width']}</td><td>{esc(r['condition'])}</td><td>{r['R']:.4f}</td><td>{r['pair_cosine']:.4f}</td><td>{r['eff_dim']:.4f}</td></tr>" for r in summary)
payload=json.dumps(requests,ensure_ascii=False).replace('<','\\u003c').replace('>','\\u003e').replace('&','\\u0026')
document='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Swarm pipeline · Team checkpoint</title><style>
:root{--ink:#15233b;--blue:#2563eb;--muted:#607087;--line:#dce4ee}*{box-sizing:border-box}body{margin:0;background:#f3f6fa;color:var(--ink);font:16px/1.55 system-ui,-apple-system,Segoe UI,sans-serif}main{max-width:1180px;margin:auto;padding:35px 24px 70px}header{padding:12px 0 22px}.eyebrow{font-size:12px;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:var(--blue)}h1{font-size:clamp(28px,4vw,43px);letter-spacing:-.035em;line-height:1.15;margin:10px 0}h2{font-size:23px;margin:0 0 15px}h3{font-size:17px}p{margin:8px 0 15px}.sub{color:var(--muted)}nav{display:flex;gap:20px;margin:18px 0 0}a{color:var(--blue)}section{background:white;border:1px solid var(--line);border-radius:16px;padding:25px;margin:20px 0}.cards,.flow{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}.card,.step{border:1px solid var(--line);border-radius:12px;padding:16px}.card strong{display:block;font-size:24px}.card span,.step p{color:var(--muted);font-size:14px}.step b{color:var(--blue)}.callout{border-left:4px solid var(--blue);background:#eff5ff;padding:12px 16px;margin:18px 0}table{border-collapse:collapse;width:100%;font-size:14px}th,td{text-align:left;padding:10px 12px;border-bottom:1px solid var(--line)}th{color:var(--muted);font-weight:600}.table-wrap{overflow:auto}.tabs{display:flex;flex-wrap:wrap;gap:8px;margin-bottom:12px}button{border:1px solid var(--line);border-radius:9px;background:white;color:var(--ink);padding:10px 13px;cursor:pointer;font:inherit;font-size:14px}button.selected{background:var(--blue);border-color:var(--blue);color:white}figure{margin:0}figcaption{color:var(--muted);font-size:14px;max-width:950px;margin:12px 0 20px}img{max-width:100%;height:auto;display:block;border:1px solid var(--line);border-radius:8px;cursor:zoom-in}details{border-top:1px solid var(--line);padding:12px 0}summary{cursor:pointer;font-weight:600}pre{white-space:pre-wrap;overflow-wrap:anywhere;background:#f5f7fb;border:1px solid var(--line);border-radius:8px;padding:16px;font:12px/1.6 Consolas,monospace;max-height:480px;overflow:auto}li{margin:7px 0}.small{font-size:13px;color:var(--muted)}dialog{border:0;border-radius:12px;padding:15px;max-width:97vw;max-height:95vh}dialog::backdrop{background:#101a2ccc}dialog img{max-height:none;max-width:90vw}dialog button{margin-bottom:10px}@media(max-width:720px){main{padding:20px 12px}.flow,.cards{grid-template-columns:1fr}section{padding:18px}nav{gap:12px;font-size:14px}}@media print{body{background:white}main{padding:0}section{break-inside:avoid;border:0;padding:14px 0}nav,.tabs,#download{display:none}.figure-panel[hidden]{display:block!important}img{max-height:650px;width:auto}pre{max-height:none}dialog{display:none}}
</style></head><body><main><header><div class="eyebrow">Team checkpoint · 14 October 2026</div><h1>A working, stateful swarm pipeline</h1><p class="sub">Real task distribution → private parallel solving → shared results → individual commits.</p><nav><a href="#pipeline">Pipeline</a><a href="#evidence">Evidence</a><a href="#graphs">Graphs</a><a href="#prompts">Exact prompts</a></nav></header>
<section id="pipeline"><h2>What was delivered</h2><div class="cards"><div class="card"><strong>10 agents</strong><span>Persistent individual histories; up to ten concurrent solving/commit calls.</span></div><div class="card"><strong>Real exchange</strong><span>Delivered distribution messages and a common packet built from actual submissions.</span></div><div class="card"><strong>Audited controls</strong><span>Independent histories, no peer deliveries or shared packet.</span></div></div><div class="flow" style="margin-top:18px"><div class="step"><b>1 · Distribute</b><p>Each agent broadcasts a preference, then claims one available task. Serial turns preserve causality; no solving yet.</p></div><div class="step"><b>2 · Solve</b><p>One task per agent, privately in parallel. Submit answer + notes ≤2000 characters. Barrier waits for all ten.</p></div><div class="step"><b>3 · Exchange / commit</b><p>Coordinator sends the same ten-result packet to everyone. Each commits all published answers once, without debate or correction.</p></div></div><div class="callout"><b>Scope:</b> the assigned task was an agent pipeline. It is implemented and verified. A cooperation classifier was not the deliverable.</div><p class="small">Upstream work supplies the ladder, legacy synthetic traces and embedding metrics. This work adds retained-context execution, protocol v2, private controls, journals, recovery, audits and comparative figures.</p></section>
<section id="evidence"><h2>Reference matched experiment · original set_4</h2><p>Original <b>set_4</b> mathematics tasks, seed 74. The private control receives the <b>same task assigned to the same agent</b>, solves once, and has no negotiation or common commit. This is not the earlier fixed-order, ten-tasks-per-agent control.</p><div class="table-wrap"><table><tr><th>Phase</th><th>Swarm calls</th><th>Verified information flow</th></tr><tr><td>Distribution</td><td>20</td><td>10 preference broadcasts + 10 claims; 180 recipient deliveries</td></tr><tr><td>Private solving</td><td>10</td><td>Zero peer deliveries</td></tr><tr><td>Shared commit</td><td>10</td><td>Same packet of ten results; all ten final maps match it</td></tr><tr><td>Independent control</td><td>10 total</td><td>Only own task/history; empty inboxes; no packet</td></tr></table></div><p><b>Both audits passed.</b> Zero action errors, interrupted continuations or missing usage receipts in this corrected pair.</p><p class="small">Generator: DeepSeek V4 Flash / Cloud.ru · temperature 1.0 · max output 32768 tokens/call · context guard 400000 bytes (not tokens). Embeddings: Qwen3-Embedding-4B / OpenRouter, 2560 dimensions, L2 normalized, no instruction prefix; DeepSeek-V3 tokenizer. Windows: 400/2048/4096, stride half-width. All answers retained regardless of correctness.</p>'''
document+=details('Matched agent → task mapping','<table><tr><th>Agent</th><th>Task</th></tr>'+assignment_rows+'</table>')
if ladder_root.exists():
    coverage=[]
    for rung in range(1,5):
        status_path=ladder_root/f'rung_{rung}/experiment.status.json'
        status=json.loads(status_path.read_text(encoding='utf-8')) if status_path.exists() else {'state':'not started','details':{}}
        coverage.append(f"<tr><td>Ladder rung {rung}</td><td>{esc(status['state'])}</td><td>{esc(status.get('details',{}).get('stage','See saved run status'))}</td></tr>")
    document+='<h3>Ladder coverage at report build</h3><table><tr><th>Dataset</th><th>Status</th><th>Stage</th></tr>'+''.join(coverage)+'</table><p class="small">Ladder graph tabs show completed figures only. Pending rungs are added when their audited workflow finishes. Rung-1 swarm is reused; each private control has matching assignments.</p>'
    if (ladder_root/'summary.json').exists():
        ladder_summaries=json.loads((ladder_root/'summary.json').read_text(encoding='utf-8'))
        table=[]
        for r in ladder_summaries:
            sw=next(v for v in r['metrics'] if v['width']==2048 and v['condition']=='Swarm v2')
            pr=next(v for v in r['metrics'] if v['width']==2048 and v['condition'].startswith('Private'))
            table.append(f"<tr><td>{r['rung']}</td><td>{sw['R']:.4f}</td><td>{pr['R']:.4f}</td><td>{sw['eff_dim']:.4f}</td><td>{pr['eff_dim']:.4f}</td></tr>")
        document+=details('Four-rung results and execution caveats','<table><tr><th>Rung</th><th>Swarm R</th><th>Private R</th><th>Swarm dimension</th><th>Private dimension</th></tr>'+''.join(table)+'</table><p>Means use relative solving progress at 2048 tokens. Similarity increases across the ladder in both populations; within-rung solving curves remain close. One pair per rung, so no statistical-equivalence or cross-rung causal claim. Rung 2 retained interrupted fragments and logged recovery; other rungs also contain some protocol errors/continuations. Audits verify integrity, not absence of operational confounds.</p>')
        task_details=[]
        for rung in range(1,5):
            ts=[json.loads(line) for line in (REPO/f'bench/ladder/rung_{rung}.jsonl').read_text(encoding='utf-8').splitlines() if line.strip()]
            task_details.append(details(f'Ladder rung {rung}: all ten task prompts',''.join(details(t['id'],block(t['prompt'])) for t in ts)))
        document+=details('All forty ladder task prompts',''.join(task_details))
document+=details('Experiment inventory and earlier control definitions','''<table><tr><th>Experiment</th><th>Purpose / status</th></tr><tr><td>Stateful v1, rung 1</td><td>Cooperative plus fixed/shuffled/cyclic controls; actual message histories and recovery journals.</td></tr><tr><td>Protocol v2, rung 1</td><td>Single distribution–solve–commit arc; simplified behavior preserved solving geometry.</td></tr><tr><td>Three groups, rung 1</td><td>Seeds 3/41/42, all four conditions; historical first groups reused and eight new runs audited.</td></tr><tr><td>Legacy offline ablation</td><td>Same saved vector pool, altered task allocation; no new generation.</td></tr><tr><td>Original set_4, seed 73</td><td>Archived: numeric-answer validation bug caused repeated solves. Not the clean comparison.</td></tr><tr><td>Original set_4, seed 74</td><td>Corrected matched one-task-per-agent pair; both audits passed without errors.</td></tr></table><p><b>Earlier control names:</b> cooperative = distribution + private solve + result exchange; fixed = each agent solves all ten tasks in the same order; shuffled = each solves all ten in its own random order; disjoint = each solves all ten with cyclic order offsets. Only cooperative receives peer information. “Disjoint” does not mean disjoint task sets. The latest matched control instead solves only one assigned task per agent.</p><p>Reference: <a href="https://docs.google.com/document/d/1QnsFs9T5jZip1CD4DlfS0O9ihRH9y92-BaYHS3t5qQg/edit">Andrey’s research plan</a> · <a href="https://github.com/DmitrySalnikov/AI-Swarm-Dynamics-Hackathon">upstream repository</a>. Original set_4 is not ladder rung_4.</p>''')
document+='''</section><section id="graphs"><h2>Graphs and interpretation</h2><div class="tabs">'''+''.join(buttons)+'''</div>'''+''.join(panels)+'''<div class="callout"><b>Reference observation (original set_4):</b> the distribution–solving–commit arc persists. With matched task allocation, the two solving populations are close. The legacy solving gap is partly reproducible from task allocation alone; its full cause is not isolated.</div>'''
document+=details('Metric definitions and original set_4 reference numbers','<p><b>R:</b> norm of the average unit vector. <b>Pairwise cosine:</b> average similarity between different agents; at fixed N it is algebraically linked to R. <b>Effective dimension:</b> covariance participation ratio, bounded by N−1. <b>N:</b> included vectors, not necessarily still-running agents in progress-aligned views. The table below is the original set_4 reference; ladder results are in the four-rung results table above.</p><table><tr><th>Window</th><th>Condition</th><th>R</th><th>Pairwise cosine</th><th>Effective dimension</th></tr>'+result_rows+'</table>')
document+='''<p class="small">The original set_4 reference pair supports a descriptive comparison, not statistical equivalence or validated detection. Swarm solve lengths: 912–4795 tokens; private: 861–33115. Repeated windows are not independent observations. Final shared format contributes to convergence.</p></section><section id="prompts"><h2>Exact protocol prompts · original set_4 reference</h2><p class="sub">Copied from recorded API requests, not reconstructed from today’s source. Agent 1 examples; agent identity, task and history vary per request.</p>'''+prompts+'''</section><section><h2>Changes, limitations and next discussion</h2><ul><li><b>v1 → v2:</b> removed optional solving chat/helper loops and iterative final discussion. One successful submit and one common commit per agent.</li><li><b>Format fix:</b> the earlier set_4 trial rejected numeric JSON answers. String and finite-number answers now canonicalize consistently in both conditions; raw responses are preserved. The affected trial is archived, not part of the clean comparison.</li><li><b>Legacy construction:</b> chats and independent solves were assembled; short swarm solves were extended with further solutions of the same question. The old shuffled bands used overlapping subsets of twenty streams.</li><li><b>Next discussion:</b> retain the simple arc and analyze changes around real exchange, or add substantive work with peer results after the packet. Changing behavior is a separate experiment; stronger interaction need not mean more similar vectors.</li></ul><p class="small">Corrected pair: generation RUB 17.58; embeddings USD 0.0098. Eight new rung-1 replication runs: local generation accounting RUB 1158.15, including estimates for unreceipted calls. Separate costs; not a combined provider invoice. No new paid work was launched to build this report.</p></section><footer class="small">Local checkpoint · standalone HTML · all figures embedded · no credentials or external resources · no Git publication</footer></main><dialog id="zoom"><button id="close">Close</button><img alt="Enlarged scientific figure"></dialog><script id="recorded-inputs" type="application/json">'''+payload+'''</script><script>
document.querySelectorAll('.tab').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('.tab').forEach(x=>{x.classList.remove('selected');x.setAttribute('aria-selected','false')});b.classList.add('selected');b.setAttribute('aria-selected','true');document.querySelectorAll('.figure-panel').forEach(x=>x.hidden=x.id!==b.dataset.target)}));
const zoom=document.getElementById('zoom');document.querySelectorAll('figure img').forEach(img=>img.addEventListener('click',()=>{zoom.querySelector('img').src=img.src;zoom.showModal()}));document.getElementById('close').onclick=()=>zoom.close();
document.getElementById('download').onclick=()=>{const blob=new Blob([document.getElementById('recorded-inputs').textContent],{type:'application/json'});const u=URL.createObjectURL(blob);const a=document.createElement('a');a.href=u;a.download='set4-seed74-recorded-inputs.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)};
</script></body></html>'''
path=OUT/'swarm-team-checkpoint.html';path.write_text(document,encoding='utf-8')
assert len(requests)==50 and len(figures)>=5
assert '<script src=' not in document and 'sk-or-v1-' not in document
print(json.dumps({'file':str(path),'size_bytes':path.stat().st_size,'figures':len(figures),'exact_inputs':len(requests)}))
